import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def process(obj):
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                if v is None:
                    continue
                v = process(v)
                if isinstance(v, str) and re.match(r"[^@\s]+@[^@\s]+\.[^@\s]+", v):
                    new[k] = REPLACE_NONE
                else:
                    new[k] = v
            return new
        elif isinstance(obj, list):
            new = []
            for v in obj:
                if v is None:
                    continue
                v = process(v)
                if isinstance(v, str) and re.match(r"[^@\s]+@[^@\s]+\.[^@\s]+", v):
                    new.append(REPLACE_NONE)
                else:
                    new.append(v)
            return new
        else:
            return obj
    def collect_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, values)
        elif isinstance(obj, list):
            for v in obj:
                collect_values(v, values)
        elif obj is not None:
            values.append(obj)
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}
    processed = process(data)
    values = []
    collect_values(processed, values)
    counts = Counter(values)
    return {"data": processed, "value_counts": counts}

